const source = $json.markdown ?? '';

const urlMap = {};
let urlCounter = 0;

function createUrlPlaceholder(url) {
  urlCounter++;
  const placeholder = `__URL_${urlCounter}__`;
  urlMap[placeholder] = url;
  return placeholder;
}

function isHugeMarkdownSeparatorLine(line) {
  const trimmed = line.trim();

  if (!trimmed) return false;

  // Удаляем пробелы, пайпы и двоеточия.
  // Если после этого остались только дефисы — это Markdown separator.
  const withoutTableChars = trimmed.replace(/[|\s:]/g, '');

  return (
    trimmed.length > 80 &&
    /^-+$/.test(withoutTableChars)
  );
}

function unwrapHugeLayoutTableLine(line) {
  const trimmed = line.trim();

  // HTML-to-Markdown иногда превращает всю рассылку в одну гигантскую строку таблицы:
  // | content | content |
  // Нам это не нужно для перевода, поэтому разворачиваем такую строку в обычный текст.
  if (
    trimmed.length > 500 &&
    trimmed.startsWith('|') &&
    trimmed.endsWith('|') &&
    !isHugeMarkdownSeparatorLine(trimmed)
  ) {
    return trimmed
      .replace(/^\|\s*/, '')
      .replace(/\s*\|$/, '')
      // Заменяем реальные разделители ячеек на абзацы.
      // Экранированные \| не трогаем.
      .replace(/([^\\])\s+\|\s+/g, '$1\n\n');
  }

  return line;
}

const cleaned = source
  // Удаляем изображения, но сохраняем текстовые ссылки
  .replace(/!\[[^\]]*]\([^)]+\)/g, '')

  // Убираем дополнительный Outlook SafeLink из title:
  // [text](main-url "duplicate-url") → [text](main-url)
  .replace(
    /\[([^\]]*)\]\((https?:\/\/[^\s)]+)\s+"[^"]*"\)/g,
    '[$1]($2)'
  )

  // Заменяем URL внутри Markdown-ссылок на плейсхолдеры
  .replace(
    /\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,
    (_match, linkText, url) => {
      const placeholder = createUrlPlaceholder(url);
      return `[${linkText}](${placeholder})`;
    }
  )

  // Удаляем пустые ссылки без текста
  .replace(/\[\s*]\([^)]+\)/g, '')

  // Построчная очистка
  .split('\n')
  .map(unwrapHugeLayoutTableLine)
  .filter(line => !isHugeMarkdownSeparatorLine(line))
  .join('\n')

  // Удаляем пустые Markdown-заголовки
  .replace(/^\s*#{1,6}\s*$/gm, '')

  // Убираем подпись пересланного/отправленного письма, если она есть
  .replace(/\n---\s*\n\\--[\s\S]*$/m, '')

  // Схлопываем длинные цепочки дефисо-подобных символов (обычно это след
  // закрашенного/отредактированного текста в оригинале), иначе они ломают
  // вёрстку на мобильных как один нераздельный кусок
  .replace(/[-\u2011\u2013\u2014_]{4,}/g, '…')

  // Убираем пробелы в конце строк
  .replace(/[ \t]+$/gm, '')

  // Ограничиваем количество пустых строк
  .replace(/\n{4,}/g, '\n\n\n')

  .trim();

const trigger = $json;

return {
  json: {
    subject: trigger.subject ?? 'Без темы',
    from: trigger.from ?? '',
    cleanedMarkdown: cleaned,
    urlMap,
    urlCount: Object.keys(urlMap).length,
    charactersBefore: source.length,
    charactersAfter: cleaned.length,
    approxTokensBefore: Math.ceil(source.length / 4),
    approxTokensAfter: Math.ceil(cleaned.length / 4),
  },
};

const content = $json.html ?? '';

const dateLabel = new Date().toLocaleDateString('ru-RU', {
  day: 'numeric',
  month: 'long',
  year: 'numeric',
});

const fullHtml = `<!doctype html>
