const buffer = Buffer.from(fullHtml, 'utf8');
const binaryData = await this.helpers.prepareBinaryData(buffer, 'newsletter-ru.html', 'text/html');

return {
  json: {
    htmlDocument: fullHtml,
  },
  binary: {
    data: binaryData,
  },
};

const previousData = $('Code in JavaScript').first().json;
const urlMap = previousData.urlMap ?? {};

function extractText(value) {
  if (typeof value === 'string') {
    return value;
  }

  if (Array.isArray(value)) {
    return value.map(extractText).join('');
  }

  if (value && typeof value === 'object') {
    if (typeof value.text === 'string') {
      return value.text;
    }

    if (typeof value.output_text === 'string') {
      return value.output_text;
    }

    if (typeof value.content === 'string') {
      return value.content;
    }

    if (Array.isArray(value.content)) {
      return value.content.map(extractText).join('');
    }

    if (value.message?.content) {
      return extractText(value.message.content);
    }

    if (value.choices?.[0]?.message?.content) {
      return extractText(value.choices[0].message.content);
    }

    if (value.output) {
      return extractText(value.output);
    }

    if (value.data) {
      return extractText(value.data);
    }
  }

  return '';
}

let restoredMarkdown = extractText(
  $json.output ??
  $json.text ??
  $json.content ??
  $json.message?.content ??
  $json.choices?.[0]?.message?.content ??
  $json
);

// Falls Modell trotzdem ```markdown ... ``` zurückgibt, entfernen
restoredMarkdown = restoredMarkdown
  .replace(/^```(?:markdown)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

// URLs aus urlMap zurücksetzen
for (const [placeholder, url] of Object.entries(urlMap)) {
  restoredMarkdown = restoredMarkdown.split(placeholder).join(url);
}

// Prüfen, ob noch Platzhalter übrig sind
const unreplacedPlaceholders = restoredMarkdown.match(/__URL_\d+__/g) ?? [];

return {
  json: {
    subject: previousData.subject ?? 'Без темы',
    from: previousData.from ?? '',
    translatedMarkdown: restoredMarkdown,
    urlCount: Object.keys(urlMap).length,
    unreplacedPlaceholders,
    charactersAfterTranslation: restoredMarkdown.length,
  },
};
